.venv/bin/python -c "
import json
r = json.load(open('reports/estimate-0.json'))
t = r['cases']['M1_P1']['timing']
def walk(d, path=''):
    if isinstance(d, dict):
        for k,v in d.items():
            if isinstance(v,(dict,list)):
                walk(v, path+'/'+k)
            else:
                print(path+'/'+k, '=', v)
walk(t['resource_stats'])" | grep -v timeline | head -120
